"""
    This function is dedicated to parse authors, it removes all the "and" but the last and and replace them with ", "
    :param str: string with authors
    :return: string with authors with only one "and"
    """
def keep_last_and_only(authors_str: Any) -> object {
    last_author = authors_str.split(" and ")[-1];
    without_and = authors_str.replace(" and ", ", ");
    str_ok = without_and.replace((", " + last_author), (" and " + last_author));
    return str_ok;
}

"""
  Takes an arbitrary number of seriesLists and adds them to a single seriesList. This is used
  to pass multiple seriesLists to a function which only takes one
  """
def group(requestContext: Any, *seriesLists: Any) -> object {
    seriesGroup = [];
    for s in seriesLists {
        seriesGroup.extend(s);
    }
    return seriesGroup;
}

